def est(x):  # rough Hindi speaking time incl. pauses at "..."
    return max(1.1, len(re.sub(r"\(.*?\)", "", x)) / 12.5 + x.count("...") * 0.35)
GAP, TAIL = 0.45, 1.0
SHOTS, LINES, t = [], [], 0.0
for sid, sc, vmin, cam, act, acting, tr, snd in SHOTDEF:
    cur = t
    for item in L.get(sid, []):
        who, x, n = item[:3]; pre = item[3] if len(item) > 3 else GAP
        cur += pre; LINES.append((round(cur, 1), who, x, n, sid)); cur += est(x)
    dur = max(vmin, cur - t + (TAIL if L.get(sid) else 0))
    SHOTS.append((sid, sc, round(t, 1), round(t + dur, 1), cam, act + (" — ACTING: " + acting if acting != "—" else ""), tr, snd))
    t = round(t + dur, 1)
DUR = t
SERIES_LINE = f"{int(DUR // 60)}:{int(DUR % 60):02d} · Day 3 se Day 10 · zyada dialogue + environment acting · long form mein DAY card nahi · 3D Zeno + 2 yudh · suspense ending"
